package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionHoursWarnVO;

class RetentionHoursWarnValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention hours warn of observability config")
  void test_retention_hours_warn_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionHoursWarnValueHolder<Object> value = new RetentionHoursWarnValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionHoursWarn(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionHoursWarnValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionHoursWarn().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention hours warn of observability config")
  void test_retention_hours_warn_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionHoursWarnValueHolder<Object> value = new RetentionHoursWarnValueHolder<>(holder);
    RetentionHoursWarnVO vo = RetentionHoursWarnVO.from(1);
    Assertions.assertFalse(value.getRetentionHoursWarnValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionHoursWarn(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionHoursWarnValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionHoursWarn(Optional.empty()));
    Assertions.assertFalse(value.getRetentionHoursWarnValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionHoursWarn(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionHoursWarnValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention hours warn of observability config against the original")
  void test_retention_hours_warn_value_holder_read() {
    Object holder = new Object();
    RetentionHoursWarnValueHolder<Object> value = new RetentionHoursWarnValueHolder<>(holder);
    RetentionHoursWarnVO vo = RetentionHoursWarnVO.from(1);
    RetentionHoursWarnVO other = RetentionHoursWarnVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionHoursWarnValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionHoursWarn(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionHoursWarn(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionHoursWarn(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionHoursWarn(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionHoursWarn(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention hours warn of observability config")
  void test_retention_hours_warn_value_holder_unset() {
    Object holder = new Object();
    RetentionHoursWarnValueHolder<Object> value = new RetentionHoursWarnValueHolder<>(holder);
    RetentionHoursWarnVO vo = RetentionHoursWarnVO.from(1);
    value.retentionHoursWarn(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionHoursWarnIfMatches("retentionHoursWarn_other"));
    Assertions.assertTrue(value.getRetentionHoursWarnValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionHoursWarnIfMatches("retentionHoursWarn"));
    Assertions.assertFalse(value.getRetentionHoursWarnValue().isPresent(),
        "The field name must clear the value");
    value.retentionHoursWarn(vo);
    Assertions.assertSame(holder, value.unsetRetentionHoursWarn());
    Assertions.assertFalse(value.getRetentionHoursWarnValue().isPresent(),
        "Unset must clear the value");
  }
}
